class Solution {
    public int maximumPossibleSize(int[] nums) {
        Deque<Integer> st = new ArrayDeque<>();
        for (int x : nums) {
            while (!st.isEmpty() && st.peekLast() > x) x = Math.max(x, st.pollLast());
            st.addLast(x);
        }
        return st.size();
    }
}

