class Solution:
    def maximumPossibleSize(self, nums: List[int]) -> int:
        n = len(nums)
        NEG, POS = float('-inf'), float('inf')
        dp = [(0, NEG)] * (n + 1)
        for i in range(1, n + 1):
            mx, best = NEG, (0, POS)
            for j in range(i, 0, -1):
                mx = max(mx, nums[j - 1])
                L, T = dp[j - 1]
                if mx >= T and (L + 1 > best[0] or (L + 1 == best[0] and mx < best[1])):
                    best = (L + 1, mx)
            dp[i] = best
        return dp[n][0]

