class Solution {
public:
    int maximumPossibleSize(vector<int>& nums) {
        int n = nums.size();
        vector<pair<int,long long>> dp(n + 1, {0, LLONG_MIN});
        for (int i = 1; i <= n; i++) {
            long long mx = LLONG_MIN;
            pair<int,long long> best = {0, LLONG_MAX};
            for (int j = i; j >= 1; j--) {
                mx = max(mx, (long long)nums[j - 1]);
                auto [L, T] = dp[j - 1];
                if (mx >= T && (L + 1 > best.first || (L + 1 == best.first && mx < best.second)))
                    best = {L + 1, mx};
            }
            dp[i] = best;
        }
        return dp[n].first;
    }
};

