class Solution {
    public int maximumPossibleSize(int[] nums) {
        int n = nums.length;
        long[][] dp = new long[n + 1][2];
        for (int i = 1; i <= n; i++) {
            long mx = Long.MIN_VALUE, len = 0, tail = Long.MAX_VALUE;
            for (int j = i; j >= 1; j--) {
                mx = Math.max(mx, nums[j - 1]);
                long L = dp[j - 1][0], T = dp[j - 1][1];
                if (mx >= T && (L + 1 > len || (L + 1 == len && mx < tail))) { len = L + 1; tail = mx; }
            }
            dp[i][0] = len; dp[i][1] = tail;
        }
        return (int) dp[n][0];
    }
}

