var maximumPossibleSize = function(nums) {
    const n = nums.length;
    const dp = Array.from({length: n + 1}, () => [0, -Infinity]);
    for (let i = 1; i <= n; i++) {
        let mx = -Infinity, len = 0, tail = Infinity;
        for (let j = i; j >= 1; j--) {
            mx = Math.max(mx, nums[j - 1]);
            const [L, T] = dp[j - 1];
            if (mx >= T && (L + 1 > len || (L + 1 === len && mx < tail))) { len = L + 1; tail = mx; }
        }
        dp[i] = [len, tail];
    }
    return dp[n][0];
};
